create database hospital_info;
use hospital_info;
create table hospital_details(patient_id int primary key,patient_name varchar(50),blood_group char(5),medical_history longtext,admission_time time,doctor_name varchar(60),treatment_cost decimal(10,2),age tinyint,bed_number smallint,total_patients bigint,medicine_price float,is_insured boolean,admission_date date,last_checkup datetime,record_timestamp timestamp default current_timestamp,patient_photo blob,doctor_notes text,patient_status enum('critical','stable','recovering','discharged'),ward_type set('general','icu','emergency','private','maternity'),room_number mediumint);
